// --- apm.FDelta
// create: apm.FDb.delta (Lary)
// global access: delta (Lary, by rowid)
// global access: ind_delta (Thash, hash field delta)
struct FDelta { // apm.FDelta: One top directory of a publish delta, with its counts
    apm::FDelta*        ind_delta_next;      // hash next
    u32                 ind_delta_hashval;   // hash value
    algo::Smallstr100   delta;               // Top directory of the changed files
    i32                 nadd;                //   0  Files the publish adds
    i32                 nmod;                //   0  Files the publish changes
    i32                 ndel;                //   0  Files the publish deletes
    // func:apm.FDelta..AssignOp
    inline apm::FDelta&  operator =(const apm::FDelta &rhs) = delete;
    // func:apm.FDelta..CopyCtor
    inline               FDelta(const apm::FDelta &rhs) = delete;
private:
    // func:apm.FDelta..Ctor
    inline               FDelta() __attribute__((nothrow));
    // func:apm.FDelta..Dtor
    inline               ~FDelta() __attribute__((nothrow));
    friend apm::FDelta&         delta_Alloc() __attribute__((__warn_unused_result__, nothrow));
    friend apm::FDelta*         delta_AllocMaybe() __attribute__((__warn_unused_result__, nothrow));
    friend void                 delta_RemoveAll() __attribute__((nothrow));
    friend void                 delta_RemoveLast() __attribute__((nothrow));
};
